from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.throughput.common_options import TypeOptions
from taf.ul.ettf.throughput.common_throughput import CommonThroughput
from taf.ul.ettf.throughput.parsers import ThroughputParser
from taf.ul.ettf.throughput.throughtput_command import ThroughputCommand
from taf.ul.ettf.throughput.validator import AssertThatThroughput, BasicValidator
from taf.ul.ettf.throughput.assertion_conditions import EqualsTo, Reaches
from taf.ul.ettf.sim.core.validators import Validators


class CellThroughputCommand(ThroughputCommand):
    def __init__(self, cell_id, enb_id, validator=Validators()):
        super(CellThroughputCommand, self).__init__('cell_stats_nr id={} enb={}'.format(cell_id, enb_id),
                                                    validator, ThroughputParser())
        self.add_param('size_unit', 'bytes')
        Command.command_elements.add_modulator('selection_type', 'Average')


class CellCommandOptions(CommonThroughput):
    def with_uec(self, uec):
        self.append_command_attribute('uec', uec)


class CellThroughputAssertions(CommonThroughput):
    def get_cell_throughput(self, cell_id, enb_id, selection_type=None):
        validator = BasicValidator(selection_type=selection_type)
        return self.init_simple_command(CellThroughputCommand(cell_id, enb_id, Validators(validator)))

    def assert_that_cell_throughput_equals(self, cell_id, enb_id, expected_throughput, selection_type=None, margin=.0):
        validator = AssertThatThroughput(EqualsTo(expected_throughput), selection_type, margin=margin)
        self.init_command(CellThroughputCommand(cell_id, enb_id, Validators(validator)))

    def assert_that_expected_cell_throughput_is_reached(self, cell_id, enb_id, expected_throughput, selection_type=None, margin=.0):
        validator = AssertThatThroughput(Reaches(expected_throughput), selection_type, margin=margin)
        self.init_command(CellThroughputCommand(cell_id, enb_id, Validators(validator)))

    def assert_that_cell_throughput(self, cell_id, enb_id):
        self.start()
        self.init_command(CellThroughputCommand(cell_id, enb_id))


class CellThroughput(CellCommandOptions, CellThroughputAssertions, TypeOptions):
    pass


